const entries = new Map();
export function put(key, value) { entries.set(key, value); }
export function get(key) { return entries.get(key); }
export function invalidate(key) { entries.delete(key); }

import { createDisposer } from './vendor/disposer-v1.mjs';
import { get, put, invalidate } from './cache.mjs';
export function mount(key, report) {
  put(key, { ready: true });
  const subscription = createDisposer(() => report(get(key).ready));
  return () => { subscription.dispose(); invalidate(key); };
}

// Exact vendored fixture dependency implementation, pinned by local SHA-256 in manifest.json.
export function createDisposer(onDispose) {
  return { dispose: () => queueMicrotask(onDispose) };
}

